/* HEXA BATTLEGROUNDS setup — PART 26 OF 57. Run parts in order. Safe to re-run. */ create or replace function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; e events; mi mission_instances; mt mission_templates; v_mission jsonb; v_battle jsonb; bi mission_instances; b battles; v_clue jsonb; v_result jsonb; v_comms jsonb; v_out jsonb; v_scan boolean; v_hidden boolean; v_board jsonb; v_role_names jsonb; v_parts jsonb; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; perform _tick(t.arena_id); select * into p from players where id = p.id; select * into t from teams where id = p.team_id; select * into a from arenas where id = t.arena_id; select * into e from events where id = t.event_id; v_scan := t.scan_until is not null and t.scan_until > now(); select * into mi from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle' order by created_at desc limit 1; if mi.id is not null then select * into mt from mission_templates where id = mi.template_id; v_mission := jsonb_build_object( 'id', mi.id, 'kind', mi.kind, 'title', mt.title, 'objective', mt.objective, 'category', mt.category, 'difficulty', mt.difficulty, 'deadline', mi.deadline, 'started_at', mi.started_at, 'attempts_left', mi.attempts_left, 'sync', mi.sync_round_id is not null, 'location', mi.location_id); if mt.relay then v_mission := v_mission || jsonb_build_object('relay', jsonb_build_object( 'partner', (select number from teams where id = mi.partner_team_id), 'fallback_at', mi.fallback_at)); end if; if p.role = 'captain' then select jsonb_agg(x -> 'label') into v_parts from jsonb_array_elements(mt.parts) x; v_mission := v_mission || jsonb_build_object('parts', v_parts, 'hint_cost', _cfg(e.id, 'hint_cost'), 'hint', case when mi.hint_used then mt.hint end, 'revealed', mi.revealed, 'reveal_cost', _reveal_cost(mi), 'revealable', (select jsonb_agg(not (x -> 'accept') ? '{KEY}') from jsonb_array_elements(mt.parts) x)); elsif p.role is not null then v_clue := mt.clues -> p.role; if (v_clue ? 'reveal_seconds') and now() > mi.started_at + _secs((v_clue ->> 'reveal_seconds')::int) then v_clue := v_clue || jsonb_build_object('body', '▒▒▒ SIGNAL LOST ▒▒▒\nThe flash has ended. Tell your captain what you remember.', 'expired', true); end if; v_mission := v_mission || jsonb_build_object('clue', v_clue); if p.role = 'intel' and mt.relay and mi.fallback_at is not null and now() >= mi.fallback_at then v_mission := v_mission || jsonb_build_object('relay_backup', mi.relay_key); end if; end if; end if; select * into bi from mission_instances where team_id = t.id and status = 'active' and kind = 'battle' limit 1; if bi.id is not null then select * into mt from mission_templates where id = bi.template_id; select * into b from battles where id = bi.battle_id; v_battle := jsonb_build_object('id', bi.id, 'battle_id', b.id, 'title', mt.title, 'objective', mt.objective, 'deadline', bi.deadline, 'started_at', bi.started_at, 'attempts_left', bi.attempts_left, 'weapon', b.weapon, 'damage', b.damage, 'attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'we_attacked', b.attacker_id = t.id); if p.role = 'captain' then select jsonb_agg(x -> 'label') into v_parts from jsonb_array_elements(mt.parts) x; v_battle := v_battle || jsonb_build_object('parts', v_parts); elsif p.role is not null then v_battle := v_battle || jsonb_build_object('clue', mt.clues -> p.role); end if; end if; select jsonb_build_object('id', x.id, 'status', x.status, 'kind', x.kind, 'points', x.points_awarded, 'title', (select title from mission_templates where id = x.template_id), 'at', coalesce(x.solved_at, x.deadline)) into v_result from mission_instances x where x.team_id = t.id and x.status <> 'active' and coalesce(x.solved_at, least(x.deadline, now())) > now() - interval '20 seconds' order by coalesce(x.solved_at, x.deadline) desc limit 1; if p.role = 'captain' then select jsonb_build_object( 'messages', coalesce((select jsonb_agg(m order by m.at) from ( select cm.id, cm.body, cm.at, (select number from teams where id = cm.from_team) as from_number, (select number from teams where id = cm.to_team) as to_number, cm.from_team = t.id as mine from chat_messages cm where cm.arena_id = t.arena_id and not cm.hidden and (cm.from_team = t.id or (cm.to_team = t.id and not exists (select 1 from chat_blocks cb where cb.team_id = t.id and cb.blocked_team = cm.from_team))) order by cm.at desc limit 80) m), '[]'::jsonb), 'blocked', coalesce((select jsonb_agg((select number from teams where id = blocked_team)) from chat_blocks where team_id = t.id), '[]'::jsonb) ) into v_comms; select coalesce(jsonb_agg(jsonb_build_object('for_team', (select number from teams where id = x.team_id), 'key', x.relay_key, 'deadline', x.deadline)), '[]'::jsonb) into v_out from mission_instances x where x.partner_team_id = t.id and x.status = 'active' and x.relay_key is not null; end if; if a.phase in ('lobby', 'boarding', 'shuttle', 'roles', 'play') then select coalesce(jsonb_agg(jsonb_build_object('number', number, 'name', name, 'points', points) order by points desc, number), '[]'::jsonb) into v_board from teams where arena_id = a.id and ready; end if; select jsonb_object_agg(r, (select display_name from players where team_id = t.id and active and role = r)) into v_role_names from unnest(array['captain', 'scout', 'decoder', 'intel']) r; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('name', e.name, 'code', e.code), 'me', jsonb_build_object('id', p.id, 'name', p.display_name, 'role', p.role), 'team', jsonb_build_object('id', t.id, 'number', t.number, 'name', t.name, 'hp', t.hp, 'shield', t.shield, 'coins', t.coins, 'points', t.points, 'trust', t.trust, 'location', t.location_id, 'state', t.state, 'travel_to', t.travel_to, 'travel_from', t.travel_from, 'travel_started_at', t.travel_started_at, 'travel_arrive_at', t.travel_arrive_at, 'recovery_deadline', t.recovery_deadline, 'attack_cooldown_until', t.attack_cooldown_until, 'protected_until', t.protected_until, 'jammed_until', t.jammed_until, 'scan_until', t.scan_until, 'beacon', t.beacon, 'ready', t.ready, 'bus', t.bus, 'dropped', t.dropped, 'visit_missions', t.visit_missions, 'visit_limit', _cfg(e.id, 'visit_missions'), 'pos', to_jsonb(_team_xy(t)), 'travel_from_xy', case when t.travel_fx is not null then jsonb_build_array(t.travel_fx, t.travel_fy) end), 'roster', (select coalesce(jsonb_agg(jsonb_build_object('name', display_name, 'role', role, 'online', last_seen_at > now() - interval '25 seconds', 'me', id = p.id) order by joined_at), '[]'::jsonb) from players where team_id = t.id and active), 'roles', v_role_names, 'arena', jsonb_build_object('id', a.id, 'number', a.number, 'name', a.name, 'phase', a.phase, 'paused', a.paused, 'shuttle_departed_at', a.shuttle_departed_at, 'shuttle_arrive_at', a.shuttle_arrive_at, 'roles_deadline', a.roles_deadline, 'zone_stage', a.zone_stage, 'zone_next_at', a.zone_next_at, 'finale_stage', a.finale_stage, 'overlay', a.overlay, 'threat', a.threat, 'results_locked', a.results_locked, 'winner_revealed', a.winner_revealed), 'mission', v_mission, 'battle', v_battle, 'last_result', v_result, 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', x.id, 'number', x.number, 'name', x.name, 'hp', x.hp, 'state', x.state, 'location', case when x.id = t.id or v_scan or x.location_id = t.location_id or x.jammed_until is null or x.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) then x.location_id end, 'pos', case when x.id = t.id or v_scan or x.location_id = t.location_id or x.jammed_until is null or x.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) then to_jsonb(_team_xy(x)) end, 'traveling', x.state = 'traveling', 'protected', x.protected_until > now(), 'in_battle', exists (select 1 from battles bb where bb.status = 'active' and (bb.attacker_id = x.id or bb.defender_id = x.id)), 'allied', exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) ) order by x.number), '[]'::jsonb) from teams x where x.arena_id = t.arena_id and x.ready), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'location', location_id, 'tier', tier, 'expires_at', expires_at)), '[]'::jsonb) from airdrops where arena_id = a.id and status = 'open'), 'inventory', (select coalesce(jsonb_object_agg(item_id, qty), '{}'::jsonb) from inventory where team_id = t.id and qty > 0), 'comms', v_comms, 'codewords', v_out, 'alliances', (select coalesce(jsonb_agg(jsonb_build_object('id', al.id, 'status', al.status, 'expires_at', al.expires_at, 'other', (select number from teams where id = case when al.team_a = t.id then al.team_b else al.team_a end), 'incoming', al.proposed_by <> t.id) order by al.created_at desc), '[]'::jsonb) from alliances al where (al.team_a = t.id or al.team_b = t.id) and al.status in ('proposed', 'active')), 'bargains', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'title', s.title, 'body', s.body, 'offer', s.offer, 'expires_at', s.expires_at)), '[]'::jsonb) from story_events s where s.arena_id = a.id and s.kind = 'bargain' and coalesce(s.expires_at, now() + interval '1 second') > now() and not (t.bargains @> jsonb_build_array(jsonb_build_object('id', s.id::text)))), 'story', (select coalesce(jsonb_agg(jsonb_build_object('title', title, 'body', body, 'at', at) order by at desc), '[]'::jsonb) from (select * from story_events where arena_id = a.id and kind in ('transmission', 'reveal') order by at desc limit 3) s), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('type', type, 'payload', payload, 'at', at) order by id desc), '[]'::jsonb) from (select * from game_feed where arena_id = a.id order by id desc limit 12) f), 'leaderboard', v_board, 'results', case when a.winner_revealed then a.results end ); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-0', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🪜 + 👨\n\n(10 letters · starts with S)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🧈 + 🪰\n\n(9 letters · starts with B)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🍯 + 🌙\n\n(9 letters · starts with H)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["STEPFATHER"]},{"label":"Picture 2 (Decoder)","accept":["BUTTERFLY"]},{"label":"Picture 3 (Intel)","accept":["HONEYMOON"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: ST…, BU…, HO…', 'STEPFATHER: step + father | BUTTERFLY: butter + fly | HONEYMOON: honey + moon', null, 25, 'published'), ('mission-pic-1', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"💡 + 🏠\n\n(10 letters · starts with L)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔥 + 🧱\n\n(8 letters · starts with F)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🔥 + 🦊\n\n(7 letters · starts with F)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["LIGHTHOUSE"]},{"label":"Picture 2 (Decoder)","accept":["FIREWALL"]},{"label":"Picture 3 (Intel)","accept":["FIREFOX"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: LI…, FI…, FI…', 'LIGHTHOUSE: light + house | FIREWALL: fire + wall | FIREFOX: fire + fox', null, 25, 'published'), ('mission-pic-2', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🌧️ + 🎀\n\n(7 letters · starts with R)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🦶 + ⚽\n\n(8 letters · starts with F)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"⭐ + 🐟\n\n(8 letters · starts with S)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["RAINBOW"]},{"label":"Picture 2 (Decoder)","accept":["FOOTBALL"]},{"label":"Picture 3 (Intel)","accept":["STARFISH"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: RA…, FO…, ST…', 'RAINBOW: rain + bow | FOOTBALL: foot + ball | STARFISH: star + fish', null, 25, 'published'), ('mission-pic-3', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🥚 + 🍆\n\n(8 letters · starts with E)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🐎 + 👞\n\n(9 letters · starts with H)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"✋ + 👜\n\n(7 letters · starts with H)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["EGGPLANT"]},{"label":"Picture 2 (Decoder)","accept":["HORSESHOE"]},{"label":"Picture 3 (Intel)","accept":["HANDBAG"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: EG…, HO…, HA…', 'EGGPLANT: egg + plant | HORSESHOE: horse + shoe | HANDBAG: hand + bag', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
